#!/usr/bin/env python3
import numpy as np, os, json, sys

# Physical constants (SI)
G   = 6.67430e-11          # m^3 kg^-1 s^-2
c   = 2.99792458e8         # m s^-1
hbar= 1.054571817e-34      # J s
k_B = 1.380649e-23         # J K^-1
M_sun = 1.98847e30         # kg

def load_gwtc_catalog():
    """Load the GWTC JSON catalog from the path given by the environment variable.
    Returns a list of dictionaries with keys: "mass_1_source", "mass_2_source", "final_mass_source".
    """
    path = os.getenv('GWTC_CATALOG_PATH')
    if not path:
        sys.exit('ERROR: GWTC_CATALOG_PATH environment variable not set')
    try:
        with open(path, 'r') as f:
            catalog = json.load(f)
    except Exception as e:
        sys.exit(f'ERROR: Could not read GWTC catalog ({e})')
    filtered = []
    for ev in catalog.get('events', []):
        m1 = ev.get('mass_1_source')
        m2 = ev.get('mass_2_source')
        mf = ev.get('final_mass_source')
        if None in (m1, m2, mf):
            continue
        filtered.append({
            'name': ev.get('name', 'unknown'),
            'm1': float(m1),
            'm2': float(m2),
            'mf': float(mf)
        })
    if not filtered:
        sys.exit('ERROR: No valid events found in the catalog')
    return filtered

def schwarzschild_radius(M):
    return 2 * G * M / c**2

def isco_radius(Spin, M):
    Z1 = 1 + (1 - Spin**2)**(1/3) * ((1 + Spin)**(1/3) + (1 - Spin)**(1/3))
    Z2 = np.sqrt(3*Spin**2 + Z1**2)
    if Spin >= 0:
        r_isco = M * (3 + Z2 - np.sqrt((3 - Z1)*(3 + Z1 + 2*Z2)))
    else:
        r_isco = M * (3 + Z1 + np.sqrt((3 - Z1)*(3 + Z1 + 2*Z2)))
    return r_isco

def photon_sphere_radius(M, a):
    return M * (1 + np.cos((2/3)*np.arccos(-a)))

def critical_impact_parameter(M, a):
    return M * (1 + np.sign(a) * np.sqrt(1 - 3*M**2 / a**2))

def radiated_fraction(event):
    return (event['m1'] + event['m2'] - event['mf']) / (event['m1'] + event['m2'])

def main():
    events = load_gwtc_catalog()
    for ev in events:
        M_tot = ev['m1'] + ev['m2']
        mf = ev['mf']
        f_rad = radiated_fraction(ev)
        print(f"{ev['name']}: radiated {f_rad:.2%}, total mass {M_tot/M_sun:.2f} M_sun")

if __name__ == '__main__':
    main()
